    "minutes": {"scores_update": 10, "top5_walk": 45, "action_note": 20, "total": 60},
    "consecutive_overruns": 2,
    "split_or_prune_required": false,
    "action_note": "Reviewed everything, nothing new."
  },
  "concentration": {
    "source": "founder_estimate",
    "trailing_days": 365,
    "recomputed_on": "2026-06-01",
    "clients": [{"name": "Client A", "share": 0.47}]
  },
  "rows": [
    {"id": "R-01", "class": "revenue_concentration", "description": "Client A might churn at some point", "likelihood": 4, "impact": 5, "score": 18, "owner": "team", "trigger": "if things get worse", "details": {"client": "Client A", "share": 0.3}, "response": null},
    {"id": "R-02", "class": "key_person", "description": "We should cross-train on the deploy pipeline", "likelihood": 3, "impact": 4, "score": 12, "owner": "ops", "trigger": "someone leaves", "details": {"item": "deploy pipeline", "holder": "Marko Ilic"}, "response": null},
    {"id": "R-03", "class": "fx_currency", "description": "Some USD exposure on a couple of clients", "likelihood": 3, "impact": 3, "score": 9, "owner": "Dana Kovac", "trigger": "the dollar moves a lot against the euro", "details": {}, "response": null},
    {"id": "R-04", "class": "pipeline_thinness", "description": "Pipeline feels thin for the autumn", "likelihood": 3, "impact": 4, "score": 12, "owner": "Dana Kovac", "trigger": "we notice there is not enough work", "details": {"weighted_pipeline": 120000, "monthly_cost_base": 60000, "months_of_coverage": 4, "trigger_below_months": 3}, "response": null},
    {"id": "P-17", "class": "project_scope_slip", "description": "Sprint 4 of the Client C build is two weeks late", "likelihood": 4, "impact": 2, "score": 8, "owner": "Marko Ilic", "trigger": "Sprint 5 also slips by more than a week", "details": {}, "response": null},
    {"id": "P-18", "class": "project_vendor", "description": "Payment gateway vendor slow on the Client B integration", "likelihood": 3, "impact": 2, "score": 6, "owner": "Marko Ilic", "trigger": "Vendor misses the next scheduled delivery date too", "details": {}, "response": null}
  ],
  "closed": []
}
